import AppShell from '../../components/AppShell';import {prisma} from '../../lib/prisma';import {getCurrentUser} from '../../lib/session';
export const dynamic='force-dynamic';
export default async function Vendors(){const user=await getCurrentUser();const vendors=await prisma.vendor.findMany({include:{vendorParts:true},orderBy:{name:'asc'}});const admin=user?.role?.name==='Admin';return <AppShell title="Vendors" active="Vendors"><div className="moduleGrid"><section className="card"><h2>Vendor Directory</h2><div className="stack">{vendors.map(v=><a className="card subtle vendorCard" key={v.id} href={`/vendors/${v.id}`}><div className="toolbar"><b>{v.name}</b><span className="badge on_hand">{v.vendorParts.length} linked parts</span></div><div className="muted">{v.contactInfo||'No contact information entered.'}</div><div className="muted">{v.leadTimeDays!=null?`Typical lead time: ${v.leadTimeDays} days`:'Lead time not set'}</div></a>)}</div></section>{admin?<section className="card"><h2>Add Vendor</h2><form action="/api/vendors" method="post" className="formgrid"><div className="field full"><label>Name</label><input name="name" required/></div><div className="field full"><label>Contact / Notes</label><textarea name="contactInfo" rows="4"/></div><div className="field"><label>Lead Time Days</label><input name="leadTimeDays" type="number" min="0"/></div><div className="field"><button className="btn primary" style={{marginTop:20}}>+ Add Vendor</button></div></form></section>:null}</div></AppShell>}
